class FakeClock:
    def __init__(self, t):
        self.t = t
    def now(self):
        return self.t

class MemRepo:
    def __init__(self):
        self.saved = []
    def save(self, order):
        self.saved.append(dict(order))

repo = MemRepo()
svc = CheckoutService(repo, FakeClock(1.0))
try:
    svc.checkout([])
except ValueError:
    pass
else:
    raise AssertionError('empty cart must raise ValueError')
